pub fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    // If the input is empty, just return an empty vector.
    if word.is_empty() {
        return Vec::new();
    }

    let mut result = Vec::with_capacity(word.len());

    // Process the first character.
    let first = word[0];
    if first.is_ascii_uppercase() {
        result.push(first);
    } else {
        // Replace any lowercase letter with 'A'
        result.push('A');
    }

    // Copy the rest of the characters unchanged.
    result.extend_from_slice(&word[1..]);

    result
}

